package com.univmar.quotation.api; import com.univmar.quotation.domain.QuotationStatus; import jakarta.validation.constraints.*; import java.math.*; import java.time.*; import java.util.*; import org.springframework.data.domain.Page;
public final class QuotationDtos {private QuotationDtos(){} public record Item(@NotBlank String materialName,@NotBlank String variantLabel,@NotNull @DecimalMin("0.001") BigDecimal quantityM2,@NotNull @DecimalMin("0") BigDecimal unitPrice,@NotNull @DecimalMin("0") @DecimalMax("100") BigDecimal discountPercent,@NotNull @DecimalMin("0") @DecimalMax("100") BigDecimal taxPercent){} public record Input(@NotNull UUID customerId,@NotNull UUID projectId,UUID rfqId,LocalDate expiryDate,@NotNull @DecimalMin("0") BigDecimal transport,String paymentTerms,String notes,@NotEmpty List<@jakarta.validation.Valid Item> items){} public record Line(UUID id,String materialName,String variantLabel,BigDecimal quantityM2,BigDecimal unitPrice,BigDecimal discountPercent,BigDecimal taxPercent,BigDecimal net,BigDecimal tax,BigDecimal total){} public record Response(UUID id,String number,UUID customerId,String customerName,UUID projectId,String projectName,UUID rfqId,String salesAgent,LocalDate expiryDate,BigDecimal transport,String paymentTerms,String notes,QuotationStatus status,int revision,BigDecimal subtotal,BigDecimal taxTotal,BigDecimal grandTotal,Instant createdAt,List<Line> items){} public record PageResult(List<Response> content,int page,int size,long totalElements,int totalPages){public static PageResult from(Page<Response> p){return new PageResult(p.getContent(),p.getNumber(),p.getSize(),p.getTotalElements(),p.getTotalPages());}} }
